import { act, cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import type { ImportDetail } from './adminApi';
import { adminWorkspace } from './adminWorkspace';
import { ImportMedia } from './ImportMedia';
import { importUploadQueue } from './importUploadQueue';
import { AdminMutation } from './useAdminMutation';
import { deferred, detail, json, projectId, session, slotId, slotTwo, viewer } from './adminFixtures.testSupport';

vi.mock('./conversionSourceValidation', () => ({ hashConversionFile: vi.fn(async () => 'a'.repeat(64)) }));
const original = '30000000-0000-4000-8000-000000000003';
function project(): ImportDetail { const item = detail(); item.capabilities.upload = true; item.upload.available = true; item.publication = 'notStarted'; return item; }
function mount(item: ImportDetail) {
  const client = new QueryClient(); client.setQueryData(['browser-session'], session);
  const element = (value: ImportDetail) => <QueryClientProvider client={client}><MemoryRouter><ImportMedia item={value} operation={new AdminMutation()} disabled={false} view="files" /></MemoryRouter></QueryClientProvider>;
  return { ...render(element(item)), element };
}
const keep = (local: Record<string, File>) => adminWorkspace.retain(`files:${projectId}`, local, adminWorkspace.capture());
const files = () => ({ [slotId]: new File(['a'.repeat(100)], '01 First.mp3'), [slotTwo]: new File(['b'.repeat(200)], '02 Second.mp3') });
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('no file needs its own dialog: Resume is the only control that sends bytes, one file at a time', async () => {
  let item = project(); const posts: string[] = []; let active = 0, max = 0;
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    if (init.method !== 'POST') return json({ item, receipt: null });
    active++; max = Math.max(max, active); posts.push(path); await new Promise(resolve => setTimeout(resolve, 2));
    const slot = decodeURIComponent(path.split('/').at(-1)!), operationId = new Headers(init.headers).get('Idempotency-Key')!;
    item = { ...item, revision: item.revision + 1, assets: [...item.assets, { slotId: slot, state: 'ready', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: 1, kind: 'upload', startedByMe: true } }] };
    active--; return json({ item, receipt: { operationId, kind: 'upload', revision: item.revision } });
  }));
  keep(files()); mount(item);
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument(); expect(posts).toHaveLength(0);
  expect(screen.getByText('0 of 2 files uploaded')).toBeVisible();
  fireEvent.click(screen.getByRole('button', { name: 'Resume upload' }));
  expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
  await vi.waitFor(() => expect(importUploadQueue(projectId).getSnapshot().running).toBe(false));
  expect(posts.map(path => path.split('/').at(-1))).toEqual([slotId, slotTwo]); expect(max).toBe(1);
});

test('Resume needs a local file and stays disabled while uploads are locked or offline', () => {
  const item = project(), view = mount(item), resume = () => screen.getByRole('button', { name: 'Resume upload' });
  expect(resume()).toBeDisabled();
  keep(files()); act(() => view.rerender(view.element({ ...item })));
  expect(resume()).toBeEnabled();
  act(() => view.rerender(view.element({ ...item, publication: 'preparing', publicationRecovery: { operationId: original, cleanupPending: false, startedByMe: true } })));
  expect(resume()).toBeDisabled(); expect(screen.getByRole('button', { name: 'Reselect folder' })).toBeDisabled();
  act(() => view.rerender(view.element({ ...item, capabilities: { ...item.capabilities, upload: false } }))); expect(resume()).toBeDisabled();
  act(() => view.rerender(view.element({ ...item })));
  vi.stubGlobal('navigator', { ...window.navigator, onLine: false }); act(() => { window.dispatchEvent(new Event('offline')); });
  expect(resume()).toBeDisabled();
});

test.each([['unavailable', 'Uploads stopped because private upload storage is unavailable.'], ['view', 'Uploads stopped after the current file because you left Admin view. Choose Resume upload to continue.'],
  ['interrupted', 'Uploads stopped because the server did not confirm the last file. Check your connection, then choose Resume upload to continue.']] as const)('a queue stopped by %s explains why and offers Resume', async (reason, message) => {
  const item = project(); keep(files()); const view = mount(item), queue = importUploadQueue(projectId);
  if (reason === 'unavailable') act(() => queue.start({ ...item, capabilities: { ...item.capabilities, upload: false } }, files(), adminWorkspace.capture()));
  else if (reason === 'interrupted') {
    vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit) => { if (init.method === 'POST') throw new TypeError('Failed to fetch'); return json({ item, receipt: null }); }));
    act(() => queue.start(item, files(), adminWorkspace.capture()));
  }
  else { const stale = adminWorkspace.capture(); act(() => { adminWorkspace.select('user'); adminWorkspace.select('admin'); }); act(() => queue.start(item, files(), stale)); }
  await vi.waitFor(() => expect(queue.getSnapshot().stopped).toBe(reason));
  act(() => view.rerender(view.element({ ...item })));
  expect(screen.getByText(message)).toBeVisible(); expect(screen.getByRole('button', { name: 'Resume upload' })).toBeEnabled();
});

test('Retry upload is offered only to the starter of an unknown upload, and Check again reconciles without bytes', async () => {
  const item = project(), requests: Array<{ path: string; init: RequestInit }> = [];
  item.assets = [{ slotId, state: 'unknown', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { operationId: original, expectedRevision: 1, kind: 'upload', startedByMe: false } }];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => { requests.push({ path, init }); return json({ item: { ...item, revision: 2, assets: [{ ...item.assets[0], state: 'ready' }] }, receipt: null }); }));
  keep(files()); const view = mount(item), row = () => screen.getByText('Synthetic Album/01 First.mp3').closest('li')!;
  expect(within(row()).queryByRole('button', { name: 'Retry upload' })).not.toBeInTheDocument();
  expect(within(row()).getByText('This upload belongs to another administrator’s operation. They can retry it. Once a check confirms it failed, any administrator can upload the file again.')).toBeVisible();
  fireEvent.click(within(row()).getByRole('button', { name: 'Check again' }));
  await vi.waitFor(() => expect(requests).toHaveLength(1));
  expect(requests[0].path).toBe(`/api/admin/v1/imports/${projectId}/assets/${slotId}/reconcile`); expect(JSON.parse(String(requests[0].init.body))).toEqual({ operationId: original });
  await vi.waitFor(() => expect(importUploadQueue(projectId).getSnapshot().latest?.assets[0].state).toBe('ready'));
  act(() => view.rerender(view.element({ ...item, assets: [{ ...item.assets[0], recovery: { ...item.assets[0].recovery!, startedByMe: true } }] })));
  expect(within(row()).getByRole('button', { name: 'Retry upload' })).toBeEnabled();
});

test('while a file uploads, the live status names it, rows show their queue state and the controls wait', async () => {
  let item = project(); const gate = deferred<void>(); let held = false;
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit) => {
    if (init.method !== 'POST') return json({ item, receipt: null });
    if (!held) { held = true; await gate.promise; }
    const slot = decodeURIComponent(path.split('/').at(-1)!), operationId = new Headers(init.headers).get('Idempotency-Key')!;
    item = { ...item, revision: item.revision + 1, assets: [...item.assets, { slotId: slot, state: 'ready', byteLength: 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: 1, kind: 'upload', startedByMe: true } }] };
    return json({ item, receipt: { operationId, kind: 'upload', revision: item.revision } });
  }));
  keep(files()); mount(item); const row = (label: string) => screen.getByText(label).closest('li')!;
  fireEvent.click(screen.getByRole('button', { name: 'Resume upload' }));
  expect(await screen.findByText('Uploading Synthetic Album/01 First.mp3')).toHaveAttribute('role', 'status');
  expect(within(row('Synthetic Album/01 First.mp3')).getByText('Uploading')).toBeVisible();
  expect(within(row('Synthetic Album/02 Second.mp3')).getByText('Waiting to upload')).toBeVisible();
  for (const name of ['Resume upload', 'Reselect folder', 'Reselect files']) expect(screen.getByRole('button', { name })).toBeDisabled();
  await act(async () => { gate.resolve(); await vi.waitFor(() => expect(importUploadQueue(projectId).getSnapshot().running).toBe(false)); });
  expect(screen.queryByText(/^Uploading /)).not.toBeInTheDocument();
});

test.each([
  [409, 'ADMIN_IMPORT_PUBLICATION_LOCKED', 'Uploads stopped because a publication now locks this import’s files.'],
  [409, 'ADMIN_IMPORT_OPERATION_LIMIT', 'Uploads stopped because this import reached its operation limit.'],
  [403, 'ADMIN_IMPORT_ADMIN_REQUIRED', 'Uploads stopped because administrator permission is unavailable.'],
  [200, 'outdated', 'The administrator workbench was updated. Reload the page to continue; unsaved edits on this page are not kept.']
] as const)('a %s %s answer stops the queue with its own explanation', async (status, code, message) => {
  const item = project(); let posts = 0;
  vi.stubGlobal('fetch', vi.fn(async (_path: string, init: RequestInit) => {
    if (init.method !== 'POST') return json({ item, receipt: null });
    posts++; const operationId = new Headers(init.headers).get('Idempotency-Key')!;
    return status === 200 ? json({ item: { ...item, futureField: true }, receipt: { operationId, kind: 'upload', revision: 2 } }) : json({ code }, status);
  }));
  keep(files()); mount(item); const queue = importUploadQueue(projectId);
  fireEvent.click(screen.getByRole('button', { name: 'Resume upload' }));
  await act(async () => { await vi.waitFor(() => expect(queue.getSnapshot().running).toBe(false)); });
  expect(posts).toBe(1); expect(screen.getByText(message)).toBeVisible();
});
